' || tA),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text and recording; no third-party passages, questions or audio copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_LISTENING_06.json 0.1.0", "audio_file": {"file": "BH-TL06-L14A_v1.mp3", "sha256": "43c73cde98d80f72fd170bea406d070152a8ebecedb73ec6c0730c363758adc4", "bytes": 3084648, "duration_seconds": 128.496, "contains": "copyright notice, 10 s silence, the first half of the discussion (to the pie charts), 2 s silence", "derived_from": {"file": "IELTS-14-L1_v2.mp3", "sha256": "15e9186ed8f4080904ad034b4554734b07a4705fb7ffdea8eca70a696492719a", "passage_seconds": [52.142, 164.302], "owner_approval": "Owner listening approval of the source recording, 2026-10-27 18:09 Asia/Bishkek"}, "method": "Cut from the approved recording with ffmpeg; no new speech; MP3 192 kbps, 48 kHz mono, copyright metadata", "human_review": "pending: owner listens to this exact file"}}'::jsonb,'468acad445fbcbbd66d86bc6007e772f059788c7860229b7f1daff7e66bbb00d',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,audio_path,audio_sha256,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-listening-l22-v1','0.1.0','Listening Lesson 14 step 2 of 6: The answer comes later','listening','guided_practice','targeted-listening-06/43c73cde98d80f72fd170bea406d070152a8ebecedb73ec6c0730c363758adc4/l22/BH-TL06-L14A_v1.mp3','43c73cde98d80f72fd170bea406d070152a8ebecedb73ec6c0730c363758adc4','You will hear two students, Amira and Josh, talking to their tutor, Professor Grant, about a presentation. Read LEARN FIRST and the worked example. Then listen to the first half of the discussion again and choose the correct letter, A, B, C or D. You may pause or replay.','In discussions the first idea is often corrected: ''at first ... but in the end'', ''the real problem was''. Keep listening until the point is settled.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "What were the students worried about at first?", "accepted_answers": ["C"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "options": [{"value": "A", "label": "A  missing the deadline"}, {"value": "B", "label": "B  getting too many responses"}, {"value": "C", "label": "C  not getting enough responses"}, {"value": "D", "label": "D  the wording of question four"}]}, {"id": "q2", "prompt": "What does Josh say was the real problem with the survey?", "accepted_answers": ["B"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "472c05b5-8cc0-43b8-b300-ae5b769d7769", "options": [{"value": "A", "label": "A  the length of the questionnaire"}, {"value": "B", "label": "B  the wording of one question"}, {"value": "C", "label": "C  the number of replies"}, {"value": "D", "label": "D  the cost of sending it"}]}, {"id": "q3", "prompt": "Why have the students had little time to analyse the replies?", "accepted_answers": ["C"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "options": [{"value": "A", "label": "A  The tutor kept the replies."}, {"value": "B", "label": "B  Some replies were lost."}, {"value": "C", "label": "C  Most replies arrived only last week."}, {"value": "D", "label": "D  They were busy with other courses."}]}, {"id": "q4", "prompt": "How long does the tutor think the background section should be?", "accepted_answers": ["D"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "options": [{"value": "A", "label": "A  about four minutes"}, {"value": "B", "label": "B  about fifteen minutes"}, {"value": "C", "label": "C  about thirty seconds"}, {"value": "D", "label": "D  about one minute"}]}, {"id": "q5", "prompt": "What is the students'' most surprising finding?", "accepted_answers": ["A"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "options": [{"value": "A", "label": "A  The smallest businesses post more often than larger ones."}, {"value": "B", "label": "B  Most businesses do not use social media."}, {"value": "C", "label": "C  Larger businesses post more often than small ones."}, {"value": "D", "label": "D  Owners do not understand social media."}]}, {"id": "q6", "prompt": "Why does the tutor suggest leaving out the history slide?", "accepted_answers": ["A"], "taxonomy_node_id": "4bdeaffb-7390-4b00-9955-69b9da537007", "supporting_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "options": [{"value": "A", "label": "A  It does not connect to their question."}, {"value": "B", "label": "B  It has too many charts."}, {"value": "C", "label": "C  The audience already knows the history."}, {"value": "D", "label": "D  It took too long to prepare."}]}]'::jsonb,'{"scope": "Targeted IELTS listening exercise; not a full paper or an official IELTS recording.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-listening-targeted-focus-v1", "passage": "LEARN FIRST: worries, plans and real problems\n\nSpeakers in Part 3 often mention something that turns out NOT to be the answer:\n- a worry that did not happen: ''we were worried at first ... but in the end ...''\n- a smaller point before the main one: ''The real problem was ...''\n- a current state that will change: ''at the moment ...''\nThe answer is what is finally true or agreed.\n\nWORKED EXAMPLE\nYou hear: ''we were worried at first that we wouldn''t get enough responses, but in the end thirty-two businesses replied, which was more than we needed.''\nWas the number of replies a problem? No. ''But in the end'' cancels the worry.\n\nNow listen and answer six questions.", "focus": "Select relevant spoken information: wait for the settled answer when speakers correct or replace a first idea."}'::jsonb || jsonb_build_object('teacher_notes', '1 C, "we were worried at first that we wouldn''t get enough responses". The worry was not realised: "more than we needed".
2 B, "The real problem was the wording." Owners misunderstood ''engagement'' in question four.
3 C, "we sent it out too late. Most replies came in last week, so we''ve had very little time to analyse them."
4 D, "I''d cut it to about one minute." Four minutes is its current length; fifteen minutes is the whole talk.
5 A, "the smallest businesses, the ones with only one or two staff, post more often than the larger ones".
6 A, "it doesn''t connect to your question. I''d leave it out altogether." The work Amira put in is not a reason to keep it.
Read each explanation, then listen to that part again and hear the proof yourself.

