' || tA),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text and recording; no third-party passages, questions or audio copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_LISTENING_06.json 0.1.0", "audio_file": {"file": "BH-TL06-L14A_v1.mp3", "sha256": "43c73cde98d80f72fd170bea406d070152a8ebecedb73ec6c0730c363758adc4", "bytes": 3084648, "duration_seconds": 128.496, "contains": "copyright notice, 10 s silence, the first half of the discussion (to the pie charts), 2 s silence", "derived_from": {"file": "IELTS-14-L1_v2.mp3", "sha256": "15e9186ed8f4080904ad034b4554734b07a4705fb7ffdea8eca70a696492719a", "passage_seconds": [52.142, 164.302], "owner_approval": "Owner listening approval of the source recording, 2026-10-27 18:09 Asia/Bishkek"}, "method": "Cut from the approved recording with ffmpeg; no new speech; MP3 192 kbps, 48 kHz mono, copyright metadata", "human_review": "pending: owner listens to this exact file"}}'::jsonb,'9a3df979506807776a0bf06e1280af4cf2fc915ed25d258a6fd54c71d3dddf4d',true) on conflict (code) do nothing;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,audio_path,audio_sha256,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-listening-l23-v1','0.1.0','Listening Lesson 14 step 3 of 6: What exactly was agreed?','listening','guided_practice','targeted-listening-06/c7a4334f8d7742e73d5cb87985269032b65ab95e22fb2e3920815641d8334572/l23/BH-TL06-L14B_v1.mp3','c7a4334f8d7742e73d5cb87985269032b65ab95e22fb2e3920815641d8334572','You will hear two students, Amira and Josh, talking to their tutor, Professor Grant, about a presentation. Read LEARN FIRST and the worked example. Then listen to the second half of the discussion and complete the notes. Write ONE WORD AND/OR A NUMBER for each answer. You may pause or replay.','Write the final, confirmed detail. A summary line such as ''So we keep ... and change ...'' or ''Fine, ... then'' usually confirms the answer.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Chart for how often each group posts: change it to a ________ chart", "accepted_answers": ["bar"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "answer_format": "text"}, {"id": "q2", "prompt": "Pie chart is still the right choice for business ________", "accepted_answers": ["size"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "1b02bd3d-3b53-4357-ad5b-3e31e3c5f5bd", "answer_format": "text"}, {"id": "q3", "prompt": "Limitations slide goes just before the ________", "accepted_answers": ["recommendations"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "fe66c90a-e788-44f7-8caa-4e0019026729", "answer_format": "text"}, {"id": "q4", "prompt": "Time on the limitations: about ________ seconds", "accepted_answers": ["thirty", "30"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "1b02bd3d-3b53-4357-ad5b-3e31e3c5f5bd", "answer_format": "text"}, {"id": "q5", "prompt": "Students'' deadline: this ________", "accepted_answers": ["Thursday"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "answer_format": "text"}, {"id": "q6", "prompt": "Send slides for comments by Wednesday ________", "accepted_answers": ["morning"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "1b02bd3d-3b53-4357-ad5b-3e31e3c5f5bd", "answer_format": "text"}]'::jsonb,'{"scope": "Targeted IELTS listening exercise; not a full paper or an official IELTS recording.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-listening-targeted-focus-v1", "passage": "LEARN FIRST: listen for the summary line\n\nWhen people discuss options, they often finish with a summary that confirms the decision:\n- ''So we keep ... and change ...''\n- ''Fine, ... then.''\n- ''Exactly.'' (the tutor agrees with a summary)\nWrite the detail from the confirmed version, not from a suggestion that was rejected.\n\nWORKED EXAMPLE\nYou hear: ''Ah. OK, Thursday it is.''\n''It is'' confirms the decision after a correction. Any earlier date mentioned before this was not the final answer.\n\nNow listen and complete six notes.", "focus": "Identify specific spoken detail: record final decisions accurately when speakers suggest and reject alternatives."}'::jsonb || jsonb_build_object('teacher_notes', '1 bar: "So we keep the pie chart for business size and change the posting one to a bar chart." The tutor confirms: "Exactly."
2 size: "No, the pie chart is the right choice for business size."
3 recommendations: "a short slide on limitations, then, just before the recommendations". Amira''s idea (at the very end) was replaced.
4 thirty / 30: "It doesn''t need long: thirty seconds would show you''ve thought critically about your own data."
5 Thursday: "Yours is still this Thursday, as planned." Next Friday is the marketing group''s deadline.
6 morning: "Send me your slides by Wednesday morning if you''d like comments."
Read each explanation, then listen to that part again and hear the proof yourself.

