' || tB),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text and recording; no third-party passages, questions or audio copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_LISTENING_06.json 0.1.0", "audio_file": {"file": "BH-TL06-L14B_v1.mp3", "sha256": "c7a4334f8d7742e73d5cb87985269032b65ab95e22fb2e3920815641d8334572", "bytes": 3255720, "duration_seconds": 135.624, "contains": "copyright notice, 10 s silence, the second half of the discussion (the charts to the end), 2 s silence", "derived_from": {"file": "IELTS-14-L1_v2.mp3", "sha256": "15e9186ed8f4080904ad034b4554734b07a4705fb7ffdea8eca70a696492719a", "passage_seconds": [164.752, 284.041], "owner_approval": "Owner listening approval of the source recording, 2026-10-27 18:09 Asia/Bishkek"}, "method": "Cut from the approved recording with ffmpeg; no new speech; MP3 192 kbps, 48 kHz mono, copyright metadata", "human_review": "pending: owner listens to this exact file"}}'::jsonb,'05008dee7d0a89decd86a9c4a07d15f6211ca081a89d8cf1cbe90dd08f375bb6',true) on conflict (code) do nothing;
